#!/usr/bin/env python3
# THE DEUTERONOMY WALK 1b — THE COMPILE OF THE OPENING SPEECH (2026-09-15): THE EXAM DOCKET for Deuteronomy 1:1-3:29 (with Numbers 27:12-23 the
# callee), written from the scan's dump (scratchpad/deu_docket_dump.txt: the LINK rows = every Babylonian Talmud / Mishnah / Tosefta segment on the
# local shelf citing a verse of the span; the TOPIC rows = the thirty Mishnah rows and the ten folio ranges of the design's item (i) read WHOLE — the
# union rule of 2026-09-05; the CREDITED marks = addresses already verdicted in an earlier ledger, given their quick look here). Every address in
# the dump gets ONE verdict (parts A..H on disk — the design said ten parts, the hand cut eight of 115 rows); the coverage is COMPUTED from the
# dump, never typed; the ranges' sizes are read from the scan's own print (deu_docket_scan.out). Append-only. write_ref_docket.py's form.
import re, os, sys, importlib.util, subprocess
from collections import Counter
ROOT = subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], text=True).strip()   # a scratch script: the repo root from git, never typed
SCR = os.path.dirname(os.path.abspath(__file__))
OUT = f'{ROOT}/logic/oral_triage/deu_01_03_devarim_exam_2026-09-15.md'
assert not os.path.exists(OUT), OUT
dump = open(f'{SCR}/deu_docket_dump.txt', encoding='utf-8').read()
rows = re.findall(r'^## \[(LINK|TOPIC)\] (.+?)  (.*)$', dump, re.M)
ADDR, CRED = [], {}
for k, a, rest in rows:
    m = re.search(r'\{CREDITED: (.*?)\}', rest)
    if m: CRED[a.strip()] = m.group(1)
    ADDR.append((k, a.strip(), re.sub(r'\s*\{CREDITED:.*?\}', '', rest).strip()))
NL = sum(1 for k, _, _ in ADDR if k == 'LINK'); NT = len(ADDR) - NL
hdr_line = dump.split('\n', 1)[0]
assert hdr_line == 'ROWS %d LINK %d TOPIC %d CREDITED %d' % (len(ADDR), NL, NT, len(CRED)), (hdr_line, len(ADDR), NL, NT, len(CRED))
V = {}
for p in 'ABCDEFGH':
    part = f'deu_docket_{p}'
    spec = importlib.util.spec_from_file_location(part, f'{SCR}/{part}.py'); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    for addr, verdict, note in m.ROWS:
        assert addr not in V, ('duplicate verdict', addr)
        assert verdict in ('LAW', 'DERIVATION', 'DISPUTE', 'CONTEXT', 'OUTSIDE'), (addr, verdict)
        V[addr] = (verdict, note)
missing = [a for _, a, _ in ADDR if a not in V]; extra = [a for a in V if a not in {x[1] for x in ADDR}]
if missing or extra:
    print('MISSING', len(missing), missing); print('EXTRA', len(extra), extra); sys.exit(1)
cnt = Counter(vd for vd, _ in V.values())
cnt_link = Counter(V[a][0] for k, a, _ in ADDR if k == 'LINK'); cnt_topic = Counter(V[a][0] for k, a, _ in ADDR if k == 'TOPIC')
works = Counter(a.rsplit(' ', 1)[0] for k, a, _ in ADDR if k == 'LINK')
scan = open(f'{SCR}/deu_docket_scan.out', encoding='utf-8').read()
scan = scan[scan.index('THE RANGES SIZED:'):]
LONG = [(f'{w.replace("_", " ")} {a}-{z}', int(s), int(l)) for w, a, z, s, l in re.findall(r'^  (\S+)\s+(\d+[ab])-(\d+[ab])\s+(\d+) segments,\s+(\d+) link rows', scan, re.M)]   # read from the scan's print
assert len(LONG) == 10, len(LONG)
MISH = [a for k, a, _ in ADDR if k == 'TOPIC' and not re.search(r'\d+[ab]:\d+$', a)]   # the Mishnah rows (Pirkei Avot 1:1 among them)
assert len(MISH) == 29, len(MISH)   # thirty named in the design, one of them (Mishnah Sotah 7:8) already a LINK row — the scan's print
assert sum(s - l for _, s, l in LONG) + len(MISH) == NT, (sum(s - l for _, s, l in LONG), len(MISH), NT)   # every range read WHOLE
ncred_link = sum(1 for k, a, _ in ADDR if k == 'LINK' and a in CRED); ncred_topic = sum(1 for k, a, _ in ADDR if k == 'TOPIC' and a in CRED)
verses = Counter(h for k, _, vs in ADDR if k == 'LINK' for h in vs.split())
LAWCELLS = Counter(m.group(1) for vd, note in V.values() if vd == 'LAW' for m in [re.search(r'\b(F[0-7])\b', note)] if m)
hdr = (f'# THE EXAM DOCKET — Deuteronomy 1:1-3:29 (the opening speech: the frame and the date, the horeb command and the land\'s bounds, the officers and the judges\' charge, the spies read back and the bar on the generation, the bypass of Seir, Moab and Ammon, Sihon and Og, the east given and the charges to the two and a half tribes and to Joshua, Moses\' plea refused) with Numbers 27:12-23 (Joshua\'s commission) as its callee, THE DEUTERONOMY WALK sitting 1b, 2026-09-15\n'
       f'# DECLARED: the exam docket is the UNION (the standing rule of 2026-09-05) of (1) THE LINK-DRIVEN ROWS — every segment of the local shelf\'s Babylonian Talmud, Mishnah and Tosefta exports whose English cites a verse of Deuteronomy 1:1-3:29 (the scan deu_docket_scan.py: {NL} rows in {len(works)} works; the verses cited most {", ".join(f"{v} {n}" for v, n in verses.most_common(6))}), and (2) THE TOPIC-ROUTED ROWS — the thirty Mishnah rows of the design\'s item (i) (Sanhedrin 1:1-6, 3:1-8, 4:1; Avot 1:1; Sheviit 9:2; Rosh Hashanah 1:1; Sotah 7:5 and 7:8; Berakhot 4:5-6; Makkot 2:4-8; Kelim 17:9-10; Eruvin 4:8 — {len(MISH)} of them topic rows, Sotah 7:8 a link row) and the ten folio ranges read WHOLE ({"; ".join(f"{n} {s} segments, {l} of them link rows" for n, s, l in LONG)}). Every address ONE verdict: LAW (names the cell of cold_run_opening_speech.py — F0 the_commission, F1 the_frame, F2 the_officers_and_the_judges, F3 the_spies_read_back, F4 the_bypass, F5 sihon_and_og, F6 the_east_and_the_charges, F7 the_plea — or the callee\'s cell by CALL; the LAW rows by cell: {", ".join(f"{c} {n}" for c, n in sorted(LAWCELLS.items()))}), DERIVATION (a hook from the verse to a rule), DISPUTE (a parameter row — a DATA row named), CONTEXT, OUTSIDE (the rows of chapter 4 and of the prayer tractate that touch nothing of chapters 1-3 — READ THEN COMPILE PER PORTION). CREDITED rows ({len(CRED)} — {ncred_link} link, {ncred_topic} topic) were verdicted in an earlier ledger and get their quick look here (the credit guards of 2026-08-25). Coverage COMPUTED by write_deu_docket.py against the scan\'s dump: {len(ADDR)} addresses, every one verdicted — missing 0, extra 0.\n'
       f'# THE TALMUD ADDRESSING: the export\'s index 0 is folio 1a (a page = index // 2 + 1; measured 2026-09-09); the Mishnah by chapter:mishnah.\n')
body = ''
last = None
for k, a, vs in ADDR:
    work = a.rsplit(' ', 1)[0]
    if work != last:
        body += f'\n## {work}\n'; last = work
    vd, note = V[a]
    body += f'- {a} [{k}{(" — " + vs) if vs else ""}{(" — CREDITED: " + CRED[a]) if a in CRED else ""}] — {vd}. {note}\n'
crowns = '''
## The finds (this docket's crowns)
- THE CHARGE READ CLAUSE BY CLAUSE (Sanhedrin 7b:14-8a:6; Yevamot 47a:7; Sanhedrin 6b:3, 6b:12-13, 7a:16-19; Tosefta Sotah 14:1): "and I charged your judges" (1:16) — charged with alacrity, with the rod and the strap; "hear between your brothers" — a judge may not hear one litigant without the other; "judge righteously" — the true judgment truly makes the Presence rest; "the stranger with him" — a convert converts only before a court (R. Yehuda), and his opponent's plea is heard (Yevamot); "you shall not respect persons" (1:17) — R. Yehuda: do not befriend the litigant, R. Elazar: do not estrange him; "the small and the great alike" — the peruta as dear as the hundred maneh, and the case that came first heard first; "you shall not be afraid before any man" — a term for gathering in: a judge may not hold back his words from fear, and a student who sees merit for the poor may not be silent; "for the judgment is God's" — Moses pierces the mountain and Aaron pursues peace; the judge who robs by his verdict loses his life, the sword between his thighs and Gehenna open beneath him. THE JUDGES' CHARGE is the DATA row the_judges_charge of F2 the_officers_and_the_judges, its ten arms on the shelf; the runner's verdict judges_charged writes the court's ledger with the charge's clauses.
- THE COMPROMISE (Sanhedrin 6b:1-15; 32b:4-6): once the verdict is issued, no compromise; R. Yehoshua ben Korcha — a mitzva to mediate ("the judgment of truth and peace in your gates", Zechariah 8:16); R. Eliezer son of R. Yosei HaGelili — forbidden, "the judgment is God's" (1:17), David's charity his own money; R. Shimon ben Menasya — before hearing, or after hearing but before knowing where the judgment leans, "go and compromise"; what is a verdict — "so-and-so, you are liable / exempt"; "justice, justice you shall pursue" (Deuteronomy 16:20) — one for judgment, one for compromise (the two boats on the river, the two camels on the ascent — yield to the laden, to the near): THREE SETTINGS ON ONE CLAUSE, the DATA row the_compromise.
- THE COURTS' ARITHMETIC AND THE OFFICERS' SECOND SEAT (Mishnah Sanhedrin 1:1-6; Sanhedrin 2a-2b; 16b:9-18; 17a:1-3, 17a:20-22): three for money, twenty-three for capital from the congregation-tokens (Numbers 35:24-25; the ten spies less Joshua and Caleb; "not after the many for evil"), seventy-one from Moses' seventy "and they shall stand there with you" (Numbers 11:16) — R. Yehuda: seventy; "judges and officers you shall set in all your gates for your tribes" (Deuteronomy 16:18) — judges for Israel, for every tribe, for every city: THE OFFICERS' TABLE's other seat, 1:15's "officers for your tribes" the first telling; "they shall bear the burden of the people WITH you" (Numbers 11:17) — like you: 1:9-12's "I cannot bear you alone" the same burden-word; the seventy-two slips and the two blanks; a Sanhedrin that all saw fit to convict acquits; only men of stature, wisdom, appearance and age who know sorcery and seventy languages, who can render a creeping thing pure by Torah law — 1:13's "wise, discerning and known" at its Talmud seat; a city of a hundred and twenty for a lesser Sanhedrin, R. Nechemya's two hundred and thirty corresponding to the captains of tens (1:15's grain).
- MONEY AGAINST CAPITAL (Mishnah Sanhedrin 4:1; Sanhedrin 32a:1-10, 32a:16, 32b:2-3, 32b:11-17): alike in inquiry and interrogation ("one manner of law", Leviticus 24:22 — the lev24 runner's own verse by REFERENCE); the ten differences — three against twenty-three, one against two, reversal, who may argue, the judge who may not reverse, by day and by night, the same day or the morrow, from the greatest or from the side (1:17's "the small and the great" the eighth's ground), all fit or the fit of lineage; the Sages removed the inquiry from money lest the doors be locked before borrowers; capital cases open with a claim to acquit — "if you did not kill, do not fear" or "by your statements so-and-so is acquitted": F2 money_and_capital, the DATA row the_ten_differences.
- THE LITIGANTS' CHOICE AND THE DISQUALIFIED (Mishnah Sanhedrin 3:1-5; Sanhedrin 23a-29a:12): this one chooses one, that one chooses one, the two choose a third so that the judgment goes out true (R. Zeira); a litigant disqualifies the other's judge and witnesses (R. Meir against the Rabbis); "my father is trusted" — the retraction before the verdict only (Reish Lakish); the disqualified by conduct — the dice-player (an asmakhta, a conditional transfer that does not acquire; or nothing added to the world's settlement), the lender AND the borrower at interest, the pigeon-flyer, the Sabbatical merchant, the robbers, the shepherds, the tax and customs collectors — a proclamation in court before any of them is disqualified, their return by breaking the dice and tearing the notes; the conspiring witness disqualified from his testimony (Abaye) or from the conviction forward (Rava); the wicked by insolence — Abaye against Rava ("do not put the wicked as a witness", Exodus 23:1 — the ordinances engine's seat); a person is his own relative and cannot make himself wicked; THE KIN from "the fathers shall not be put to death for the children" (Deuteronomy 24:16) — not BY the children's testimony, the plural for the cousins, "fathers" twice for the mother's side, "shall not be put to death" twice for the benefit and the detriment, "one manner of law" for money, a husband as his wife; THE LOVER AND THE HATER from "he was not his enemy nor sought his harm" (Numbers 35:23) — the groomsman and the three days' enmity, the witness disputed and THE JUDGE agreed: 1:17's "no faces" the DATA row no_faces with its Talmud arms.
- THE EXAMINATION, THE VERDICT AND THE NEW PROOF (Mishnah Sanhedrin 3:6-8; Sanhedrin 29a:13-31b:12): the witnesses brought in and intimidated — "clouds and wind without rain", "a hammer, a sword, a sharp arrow", Jezebel's "two base fellows"; "say how you know" — "he admitted in our presence" stands, "he told me" says nothing; "you are my witnesses" (Rav) — the jesting admission, the witnesses hidden behind the fence exempt unless he claimed the matter never was; the admission's record before two with an act, before three sitting as a court; the divided court's verdict written "exempt" (R. Yochanan — "you shall not go as a talebearer", Leviticus 19:16) or with the names (Reish Lakish); the witnesses together or apart (R. Natan), seeing together or apart (R. Yehoshua ben Korcha) — "one witness shall not rise" (Deuteronomy 19:15) the two; the contradiction in the examination's details valid in money, not in capital; the new proof overturns until "bring all your proofs within thirty days" — Rabban Shimon ben Gamliel: what could he do who did not know?; "write me the reason you judged me so" — the judges write it; the inciter denied the court's plea, from the primordial serpent — and whoever adds subtracts (Eve's "nor touch it"; "two cubits and a half" / "eleven curtains" — the parser's own numerals read as letters on the shelf): F2 hear and the_judgment_is_gods, the DATA rows the_examination and the_verdict.
- THE DATE'S CHAIN (Mishnah Rosh Hashanah 1:1; Rosh Hashanah 2b:7-3a:16; Rambam's Introduction 2:19): the kings' years from Nisan by 1 Kings 6:1's four hundred and eightieth year; Deuteronomy 1:3's "fortieth year" the exodus's by the verbal analogy with Numbers 33:38's "fortieth year … of the going out" (Rav Pappa) — THE TRANSFER THAT DATES THE SPEECH'S MARKER at (40, 11, 1); Aaron's death before the speech by "after he had smitten Sihon" (1:4); the Canaanite king of Arad heard that Aaron died and the clouds departed; Av and Shevat one year, not Iyar — "the first month of the second year" (Exodus 40:17) and "the second year, the second month, the twentieth" (Numbers 10:11) one year; not Sivan, Tammuz, Av or Adar; Solomon's "second month in the second" (2 Chronicles 3:2); Artaxerxes' Kislev and Nisan: F1 the_frame's the_date, ONE CLOCK, TWO READERS (the marker read by the number reader, the era by the taught analogy; JO.aarons_death_retold('verbal_analogy') by CALL).
- THE SPIES ON THE SHELF, THE READBACK'S SPECIMENS (Sotah 34b:3-4, 34a:9-35a:13; Shevuot 47b:5; Sanhedrin 2a:15): "send for yourself" (Numbers 13:2) — at your discretion, the people asked (1:22, Reish Lakish); "that they may search the land for us" (veyachperu, 1:22) — the digging and the embarrassment; the cluster on a pole between two; Caleb alone at the graves of the fathers ("and HE came to Hebron"; 1:36 "because he wholly followed"); Joshua kept by Moses' prayer; the going likened to the coming; "it flows with milk and honey — however" the lie with a grain of truth (1:25's "good is the land" keeps the truth, the retelling graded SHORTENED); "stronger than us" read "than Him" (1:28's "greater and taller than we" the plain sense, graded TURNED); the night of weeping the eve of the Ninth of Av (1:27 "you murmured in your tents" — Shimon ben Tarfon's two words, you explored and disparaged; 1:34 "the LORD heard the voice of your words"); the ten spies the congregation-token: F3 the_spies_read_back's reference rows READ AGAINST THE TAPE'S OWN LINES (the readback's first form, ruled "Yes 1. Go").
- MOAB, AMMON, ESAU (Bava Kamma 38a:16-38b:6; Horayot 10b:19-11a:1; Nazir 23b:11-12; Kiddushin 18a:2; Nazir 61a:11; Chullin 60b:13): "do not contend with Moab in battle" (2:9) — battle forbidden, harassing not, the reward of the elder daughter's euphemism; "neither harass them nor contend" (2:19) — Ammon not even harassed, the reward of the younger's; what entered Moses' mind — his own a fortiori from Midian, the bar needed; "I have given Mount Seir to Esau as an inheritance" (2:5) and "Ar to the sons of Lot" (2:9) — a gentile inherits by Torah law (R. Yochanan); Israel forbidden Moab's land, Sihon took it, Israel took it from Sihon (Numbers 21:26 — the chukat runner's row): F4 the_bypass's three bars the DATA rows edom / moab / ammon, the two bars' difference a PARAMETER; the effect contending_barred on the three peoples.
- THE FIFTEENTH OF AV (Taanit 30b:12; Bava Batra 121b:1): "when all the men of war were consumed … the LORD spoke to me" (2:16-17) — the deaths in the wilderness ceased, the speech resumed, the day of the wood-offering and of the tribes' intermarriage: F4 the_bypass's zered_crossing_commanded the debit CLOSED BY A PRIOR RUN (Numbers 21:12 the tape's earlier line); the thirty-eight years (2:14) the clock's own arithmetic (the CD-era verses).
- THE SUN FOR MOSES (Avodah Zarah 25a:7-9; Taanit 20a:6-8): "this day I will begin to put the dread of you" (2:25) — "I will begin" / "I will begin" (Joshua 3:7) and "put" / "put" (Joshua 10:12) the two verbal analogies, R. Yochanan from the verse itself ("the peoples under the whole heaven shall tremble"): the sun stood still for Moses as for Joshua — F4 sihon_war_commanded's dread clause, the run outside the Torah; the Torah's own hypothesis row (no act on the tape — the dread a status, not a day).
- THE PLEA (Berakhot 32a:32; Avodah Zarah 7b:18; Berakhot 30b:9; Sotah 13b:13; Kiddushin 29a:14; Gittin 56b:1; Mishnah Berakhot 4:5-6; Berakhot 30a:9; Tosefta Berakhot 6:1): "and I besought the LORD at that time" (3:23) — praise first ("You have begun to show Your servant Your greatness", 3:24) then the request ("let me go over", 3:25): R. Simlai's order of prayer; "I pleaded" against "Moses besought" (Exodus 32:11) the two modes; "let it suffice you" (rav lakh, 3:26) measure for measure for Korach's "enough for you" (Numbers 16:3 — the korach runner's token by REFERENCE); "command Joshua, encourage and strengthen him" (3:28) — "command" a galvanization, immediate and for generations; "that good mountain and Lebanon" (3:25) — Lebanon the Temple (Isaiah 10:34); the direction of prayer toward the Temple, the heart toward the Holy of Holies, "by way of their land which You have given to their fathers" (1 Kings 8:48): F7 the_plea's moses_besought — plea_made with the refusal in the value; the direction of prayer the DATA row the_directions (four directions in three orders).
- THE WORDS AS SINS (Berakhot 32a:7; Sanhedrin 102a:14; Mishnah Sotah 7:8; Sotah 41a:18; Tosefta Sotah 7:9; Zevachim 115b:17; Sotah 35b:6): "and Di-zahab" (1:1) — the school of R. Yannai: no such place — the calf's gold, "enough" of gold; the king reads from "these are the words" at the assembly; R. Akiva: the generalities and the details at Sinai, repeated in the Tent, a third time in the plains of Moab; "Moses undertook to expound this Torah" (1:5) with "clearly elucidated" (Deuteronomy 27:8) — the seventy languages: F1 the_frame's the_words (the Sifrei 1's places as sins, Onkelos' verse), the effect torah_expounded on israel_people at 1:5.
- THE SIXTY CITIES AND THE VERSES FIT TO BE BURNED (Arakhin 32b:6, 33b:22; Megillah 10a:10; Shevuot 16a:14; Chullin 60b:11-14; Sanhedrin 90b-91a): "sixty cities, all the region of Argob, fortified with high walls, gates and bars" (3:4-5) — the walled cities from Joshua's days many, the Sages enumerated the re-sanctified; "walled" (Leviticus 25:29) learned from 3:5 by the verbal analogy; "the Avvim … the Caphtorim destroyed them" (2:23) and "Hermon the Sidonians call Sirion" (3:9) — Reish Lakish's verses fit to be burned that are the Torah's body: the dispossessions read whole; Geviha ben Pesisa against Afrikiya on the land's title (Canaan a slave), "to give THEM" (Deuteronomy 11:21) — the land promised to the dead fathers (1:8's refrain): F5 sihon_and_og's the_sixty_cities and F4's the_dispossessions, the DATA rows.
- THE LAND'S KINDS, THE GENERATION'S SONS, THE BLESSING'S ADDITION (Bava Kamma 81b:6; Eruvin 100b:18; Nedarim 20b:10; Rosh Hashanah 28b:10; Avodah Zarah 37b:15; Mishnah Sheviit 9:2; Mishnah Kelim 17:9-10; Mishnah Eruvin 4:8): "the hill country, the lowland, the Negev, the seashore" (1:7) — every tribe's portion holds some of each kind (Joshua's ten conditions); the three lands for the removal — Judea, Transjordan, Galilee, three in each (the Sifrei 6:1's regions); "wise and discerning and known" (1:13) against "wise and known" (1:15) — the discerning not found, the generation's sons; "may the LORD add to you a thousand times" (1:11) — a priest may not add this blessing of his own; "food for money, water for money" (2:28) — food like water; the cubit of which they spoke the medium one, Og's bed "by the cubit of a man" (3:11): F2's the_seven_qualities and the_officers_table, F1's the_bounds, F5's ogs_bed the DATA rows.
- THE EASTERN REFUGE CITIES ARE CHAPTER 4's (Makkot 9b:18; 10a:9-16; Mishnah Makkot 2:4-8): Moses designated three beyond the Jordan — "then Moses separated three cities toward the sunrise" (Deuteronomy 4:41-43), "a mitzva that came my way"; the six cities and the roads: the refuge runner's rows CREDITED by CALL; the three of chapter 4 OUTSIDE this compile — READ THEN COMPILE PER PORTION, the debit open by design (the refuge docket's own crown) to be CLOSED at chapter 4's sitting, not before.
'''
cite = '\n## CITE INDEX — every segment opened, each fully named\n(coverage COMPUTED by write_deu_docket.py against the scan\'s dump: %d addresses, every one verdicted — missing 0, extra 0)\n' % len(ADDR)
cite += '\n'.join(a for _, a, _ in ADDR) + '\n'
tail = (f'\n**read: {len(ADDR)} of {len(ADDR)} — COMPLETE** (the link-driven rows {NL}: {", ".join(f"{k} {n}" for k, n in sorted(cnt_link.items()))}; '
        f'the topic windows {NT}: {", ".join(f"{k} {n}" for k, n in sorted(cnt_topic.items()))}; all rows: {", ".join(f"{k} {n}" for k, n in sorted(cnt.items()))}; credited {len(CRED)} — the counts this script computed from the dump and the verdict lists, never typed).\n')
open(OUT, 'w', encoding='utf-8').write(hdr + body + crowns + cite + tail)
print('WROTE', OUT, os.path.getsize(OUT), 'bytes')
print('rows', len(ADDR), 'link', NL, 'topic', NT, 'credited', len(CRED), '(link', ncred_link, 'topic', ncred_topic, ')')
print('verdicts', dict(sorted(cnt.items())), 'link', dict(sorted(cnt_link.items())), 'topic', dict(sorted(cnt_topic.items())))
print('LAW by cell', dict(sorted(LAWCELLS.items())))
print('ranges', [(n, s, l) for n, s, l in LONG]); print('mishnah rows', len(MISH))
